import java.util.*;
import java.io.*;

public class Main {
    static final int Lg = 18;
    static final int Tw = 1 << Lg;
    static final int Max = Tw + 10;
    static int[][] Ans = new int[Max][Lg + 3];
    static int[] tmp = new int[Lg + 3];
    static int[] tmp2 = new int[Lg + 3];
    static int[] fac = new int[Max];
    static int[] ifac = new int[Max];
    static int N, n, mod;
    static List<Integer> bits = new ArrayList<>();

    static int power(int a, int b) {
        long res = 1;
        long base = a;
        while (b > 0) {
            if ((b & 1) == 1) {
                res = (res * base) % mod;
            }
            base = (base * base) % mod;
            b >>= 1;
        }
        return (int) res;
    }

    static void addArrays(int[] a, int[] b) {
        for (int i = 0; i <= N; i++) {
            a[i] = (a[i] + b[i]) % mod;
        }
    }

    static void subtractArrays(int[] a, int[] b) {
        for (int i = 0; i <= N; i++) {
            a[i] = (a[i] - b[i]) % mod;
            if (a[i] < 0) a[i] += mod;
        }
    }

    static void multiplyArrays(int[] ans, int[] a, int[] b) {
        Arrays.fill(tmp, 0);
        for (int i = 0; i <= N; i++) {
            for (int j = 0; j <= i; j++) {
                tmp[i] = (int) ((tmp[i] + (long) a[j] * b[i - j]) % mod);
            }
        }
        System.arraycopy(tmp, 0, ans, 0, tmp.length);
    }

    static void transformForward(int[][] a) {
        for (int i = 0; i < N; i++) {
            for (int msk = n; msk >= 0; msk--) {
                if (((msk >> i) & 1) == 1) {
                    addArrays(a[msk], a[msk ^ (1 << i)]);
                }
            }
        }
    }

    static void transformInverse(int[][] a) {
        for (int i = 0; i < N; i++) {
            for (int msk = n; msk >= 0; msk--) {
                if (((msk >> i) & 1) == 1) {
                    subtractArrays(a[msk], a[msk ^ (1 << i)]);
                }
            }
        }
    }

    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        int K = sc.nextInt();
        N = sc.nextInt();
        mod = sc.nextInt();

        int answer = power(K, N);
        if ((N & 1) == 1) {
            System.out.println(answer);
            return;
        }

        int N_before = N;
        bits.clear();
        for (int i = 0; i < Lg; i++) {
            if (((N >> i) & 1) == 1) {
                bits.add(i);
            }
        }
        n = (1 << N) - 1;

        fac[0] = 1;
        for (int i = 1; i < Max; i++) {
            fac[i] = (int) ((long) i * fac[i - 1] % mod);
        }
        ifac[Max - 1] = power(fac[Max - 1], mod - 2);
        for (int i = Max - 2; i >= 0; i--) {
            ifac[i] = (int) (((long) (i + 1) * ifac[i + 1]) % mod);
        }

        for (int i = 0; i <= n; i++) {
            int Real = 0;
            for (int j = 0; j < N; j++) {
                if (((i >> j) & 1) == 1) {
                    Real += (1 << bits.get(j));
                }
            }
            Ans[i][Integer.bitCount(i)] = ifac[Real];
        }

        transformForward(Ans);

        for (int i = 0; i <= n; i++) {
            int KK = K;
            Arrays.fill(tmp2, 0);
            tmp2[0] = 1;
            while (KK > 0) {
                if ((KK & 1) == 1) {
                    multiplyArrays(tmp2, tmp2, Ans[i]);
                }
                multiplyArrays(Ans[i], Ans[i], Ans[i]);
                KK >>= 1;
            }
            System.arraycopy(tmp2, 0, Ans[i], 0, tmp2.length);
        }

        transformInverse(Ans);

        answer = (answer - (int) ((long) Ans[n][N] * fac[N_before] % mod)) % mod;
        if (answer < 0) answer += mod;
        System.out.println(answer);
    }
}
